votes = ["tea", "coffee", "tea", "juice", "tea", "coffee"]
tally = {}
for drink in votes:
    tally[drink] = tally.get(drink, 0) + 1
print(tally)

menu = {"chai": 20, "samosa": 15, "vada pav": 25, "lassi": 40}
total = 0
line = input("Order: ")
while line != "done":
    *words, qty = line.split()
    item = " ".join(words)     # "vada pav" has two words
    qty = int(qty)
    if item in menu:
        total += menu[item] * qty
    else:
        print(f"Sorry, we don't have {item}")
    line = input("Order: ")
print(f"Total: ₹{total}")

